# Find all triples (a,b,c) with a<=b<=c, positive integers, such that
# ab-c, bc-a, ca-b are all powers of 2 (including 2^0=1)

def is_pow2(n):
    return n > 0 and (n & (n-1)) == 0

solutions = []
N = 200
for a in range(1, N+1):
    for b in range(a, N+1):
        for c in range(b, N+1):
            x = a*b - c
            y = b*c - a
            z = c*a - b
            if is_pow2(x) and is_pow2(y) and is_pow2(z):
                solutions.append((a,b,c, x, y, z))

for s in solutions:
    print(s)
