def is_pow2(n):
    return n > 0 and (n & (n-1)) == 0

solutions = []
N = 2000
for a in range(1, N+1):
    for b in range(a, N+1):
        max_u_val = b * (a - 1) if a > 1 else 0
        u_val = 1
        while u_val <= max_u_val:
            c = a * b - u_val
            if c >= b:
                y = b * c - a
                z = c * a - b
                if is_pow2(y) and is_pow2(z):
                    solutions.append((a, b, c, u_val, y, z))
            u_val *= 2
            if u_val == 0:
                break

for s in solutions:
    print(s)
print(f"Total: {len(solutions)}")
